fn determine_winner(a: i8, b: i8, c: i8, d: i8) -> String {
    fn score(p: i32, t: i32) -> i32 {
        let s1 = 3 * p / 10;
        let s2 = p - (p * t) / 250;
        if s1 > s2 { s1 } else { s2 }
    }

    // Interpret inputs as:
    // a = P1, b = T1, c = P2, d = T2
    let p1 = a as i32;
    let t1 = b as i32;
    let p2 = c as i32;
    let t2 = d as i32;

    let s_misha = score(p1, t1);
    let s_vasya = score(p2, t2);

    if s_misha > s_vasya {
        "Misha".to_string()
    } else if s_vasya > s_misha {
        "Vasya".to_string()
    } else {
        "Tie".to_string()
    }
}